/**
 * SLATE — what each genre is and what it asks of an actor (from the connected attributes of 2026-10-09), read by
 * `systems/engagement.ts` and `systems/evaluation.ts`.
 *
 * Generated from `docs/research/attributes/research-genres.json` by the research of 2026-10-09: each genre's
 * conventions as a cited source defines them (`how` says whether the source was read directly or only from a search's
 * summary), the families it belongs to, and what it asks of a performer. Its spelling and a few joins are the
 * house's, edited after generation (`tools/spelling.mjs`, `tools/tics.mjs`); the research file keeps the original. Of the 149, the demands of 30 are sourced
 * (`demandsSource`, medium confidence); the other 119 are the researcher's reading of the conventions, said so by
 * `demandsConfidence: 'low'` and on the genre's look. No work is named here: a genre's practice is the plays and
 * films the game already has, or a film of the kind with no title given.
 *
 * A genre's family leans what a piece of work's dimensions count for (`EVALUATION.familyLean`). What a person has of
 * a genre is three things kept apart (`systems/engagement.ts`): whether they love it (the character sheet),
 * how familiar they are with it (watched, read, seen), and their practice in it (work done in it). Familiarity and
 * practice speed preparation; none of them caps what the work can reach.
 */

export type Family =
  | 'action' | 'adventure' | 'animation' | 'comedy' | 'crime' | 'documentary' | 'drama' | 'experimental' | 'fantasy'
  | 'farce' | 'historical' | 'horror' | 'melodrama' | 'musical' | 'mystery' | 'romance' | 'satire' | 'science_fiction'
  | 'thriller' | 'tragedy' | 'war' | 'western';

export interface GenreDef {
  families: readonly Family[];
  /** Its conventions, as its source defines them. */
  conventions: string;
  /** What it asks of a performer. */
  demands: string;
  source: string;
  how: string;
  demandsSource?: string;
  demandsConfidence: 'high' | 'medium' | 'low';
}

