/** The families of a piece of work's genres, once each: a play that's two kinds of comedy is comedy once. */
export function familiesOf(genres: readonly string[]): Family[] {
  return [...new Set(genres.flatMap((g) => GENRE_DEFS[g]?.families ?? []))];
}
